def evaluate(expr: str) -> float:
    """
    Evaluates an arithmetic expression without using eval, exec, compile or ast module.

    Args:
    expr (str): The arithmetic expression to evaluate.

    Returns:
    float: The result of the evaluated expression.

    Raises:
    ZeroDivisionError: When dividing by zero.
    ValueError: For malformed input (unknown characters, unbalanced parentheses, missing operands, empty string).
    """

    # Define operator precedence
    precedence = {'+': 1, '-': 1, '*': 2, '/': 2}

    # Define operator functions
    operators = {
        '+': lambda a, b: a + b,
        '-': lambda a, b: a - b,
        '*': lambda a, b: a * b,
        '/': lambda a, b: a / b if b != 0 else float('inf')
    }

    # Tokenize the expression
    tokens = []
    num = ''
    for char in expr:
        if char.isdigit() or char == '.':
            num += char
        elif char in precedence or char == '(' or char == ')':
            if num:
                tokens.append(float(num))
                num = ''
            if char != ' ':
                tokens.append(char)
    if num:
        tokens.append(float(num))

    # Parse the expression
    output = []
    stack = []
    for token in tokens:
        if token == '(':
            stack.append(token)
        elif token == ')':
            while stack and stack[-1] != '(':
                output.append(stack.pop())
            if stack and stack[-1] == '(':
                stack.pop()
        elif token in precedence:
            while stack and stack[-1] in precedence and precedence[stack[-1]] >= precedence[token]:
                output.append(stack.pop())
            stack.append(token)
        else:
            output.append(token)
    while stack:
        output.append(stack.pop())

    # Evaluate the expression
    output = output[::-1]
    stack = []
    for token in output:
        if token in precedence:
            b = stack.pop()
            a = stack.pop()
            stack.append(operators[token](a, b))
        else:
            stack.append(token)
    return stack[0]
