def validate(data: dict, schema: dict[str, type]) -> list[str]:
    """
    Validate a dictionary against a schema.

    Args:
    - data (dict): The data to validate.
    - schema (dict): The schema to validate against.

    Returns:
    - list[str]: A sorted list of error strings. If the data is valid, an empty list is returned.
    """
    errors = []
    for field, field_type in schema.items():
        if field not in data:
            errors.append(f"missing: {field}")
        elif not isinstance(data[field], field_type):
            if field_type == bool and isinstance(data[field], int):
                continue
            if field_type in [int, float] and isinstance(data[field], int):
                continue
            errors.append(f"type: {field}")
    for field in data:
        if field not in schema:
            errors.append(f"extra: {field}")
    return sorted(errors)
