def vigenere_encrypt(text: str, key: str) -> str:
    """Encrypts text using Vigenere cipher with the given key."""
    if not key.isalpha():
        raise ValueError("Key must only contain letters")
    key = key.lower()
    result = ""
    key_index = 0
    for char in text:
        if char.isalpha():
            shift = ord(key[key_index]) - ord('a')
            if char.isupper():
                result += chr((ord(char) - ord('A') + shift) % 26 + ord('A'))
            else:
                result += chr((ord(char) - ord('a') + shift) % 26 + ord('a'))
            key_index = (key_index + 1) % len(key)
        else:
            result += char
    return result


def vigenere_decrypt(text: str, key: str) -> str:
    """Decrypts text using Vigenere cipher with the given key."""
    if not key.isalpha():
        raise ValueError("Key must only contain letters")
    key = key.lower()
    result = ""
    key_index = 0
    for char in text:
        if char.isalpha():
            shift = ord(key[key_index]) - ord('a')
            if char.isupper():
                result += chr((ord(char) - ord('A') - shift) % 26 + ord('A'))
            else:
                result += chr((ord(char) - ord('a') - shift) % 26 + ord('a'))
            key_index = (key_index + 1) % len(key)
        else:
            result += char
