def insert_position(xs: list[int], x: int) -> int:
    """Return the leftmost index where `x` could be inserted keeping the list sorted."""
    left, right = 0, len(xs)
    while left < right:
        mid = (left + right) // 2
        if xs[mid] < x:
            left = mid + 1
        else:
            right = mid
    return left

def count_occurrences(xs: list[int], x: int) -> int:
    """Return how many times `x` appears in the list."""
    return insert_position(xs, x + 1) - insert_position(xs, x)
