        self.server_socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        self.server_socket.bind((self.host, self.port))
        self.server_socket.listen()
        print(f"Server listening on {self.host}:{self.port}")
        return self.port

    def stop(self):
        for client_socket, client_name in self.clients.items():
            client_socket.send(b"SERVER_SHUTDOWN")
            client_socket.close()
        self.server_socket.close()

    def handle_client(self, client_socket, client_address):
        try:
            client_name = None
            while True:
                data = client_socket.recv(1024)
                if not data:
                    break
                data = data.decode("utf-8").strip()
                if client_name is None:
                    if data.startswith("NAME "):
                        username = data[5:]
                        with self.lock:
                            if username not in self.clients:
                                client_name = username
                                self.clients[client_name] = client_socket
                                for other_client_name, other_client_socket in self.clients.items():
                                    if other_client_name != client_name:
                                        other_client_socket.send(f"* {client_name} joined\n".encode("utf-8"))
                                client_socket.send("OK\n".encode("utf-8"))
                            else:
                                client_socket.send("ERROR name taken\n".encode("utf-8"))
                                break
                    else:
                        client_socket.send("ERROR invalid command\n".encode("utf-8"))
                        break
                else:
                    for other_client_name, other_client_socket in self.clients.items():
                        if other_client_name != client_name:
                            other_client_socket.send(f"{client_name}: {data}\n".encode("utf-8"))
        except Exception as e:
            print(f"Error handling client {client_address}: {e}")
        finally:
            with self.lock:
                if client_name is not None:
                    self.clients.pop(client_name)
                    for other_client_name, other_client_socket in self.clients.items():
                        other_client_socket.send(f"* {client_name} left\n".encode("utf-8"))

    def serve_forever(self):
        while True:
            client_socket, client_address = self.server_socket.accept()
            client_thread = threading.Thread(target=self.handle_client, args=(client_socket, client_address))
            client_thread.start()

    def start_serving(self):
