class NotFound(Exception):
    pass

class MethodNotAllowed(Exception):
    pass

class Router:
    def __init__(self):
        self.routes = {}

    def add(self, method: str, pattern: str, handler):
        self.routes.setdefault(method, []).append((pattern, handler))

    def dispatch(self, method: str, path: str) -> tuple[handler, dict[str, str]]:
        path = path.rstrip('/')
        for pattern, handler in self.routes.get(method, []):
            segments = pattern.split('/')
            path_segments = path.split('/')
            if len(segments) != len(path_segments):
                continue
            params = {}
            for i, (seg, path_seg) in enumerate(zip(segments, path_segments)):
                if seg == '{' and i < len(path_segments) - 1 and path_segments[i + 1] != '}':
                    params[path_segments[i + 1]] = path_segments[i + 2]
                    i += 2
                elif seg != path_seg:
                    break
            else:
                return handler, params
        raise NotFound(f"No route found for {path}")
        raise MethodNotAllowed(f"Method not allowed for {path}")

def route(method: str, pattern: str):
    def decorator(handler):
        router.add(method, pattern, handler)
        return handler
    return decorator

def create_router():
    return Router()
